targets.expr:
sort_desc(
  sum by (component) (
    label_replace(
      kube_pod_info{
        pod=~"thanos-(compactor|storegateway|ruler|receive(?:-distributor)?|query(?:-frontend)?).*",
        container!=""
      },
      "component", "$1", "pod",
      "thanos-(compactor|storegateway|ruler|receive(?:-distributor)?|query(?:-frontend)?).*"
    )
  )
)

max(
  sum by (pod) (
    kube_pod_container_resource_limits{
      resource="cpu",
      namespace="monitoring",
      pod=~"thanos-query.*",
      pod!~"thanos-query-frontend-.*"
    }
  )
)

max by (pod) (
  irate(
    container_cpu_usage_seconds_total{
      namespace="monitoring",
      container="query",
      pod=~"thanos-query.*",
      pod!~"thanos-query-frontend.*"
    }[$__rate_interval]
  )
)

max(
  sum by (pod) (
    kube_pod_container_resource_requests{
      resource="cpu",
      namespace="monitoring",
      pod=~"thanos-query.*",
      pod!~"thanos-query-frontend.*"
    }
  )
)

max(
  max by (pod) (
    kube_pod_container_resource_limits{
      resource="memory",
      namespace="monitoring",
      pod=~"^thanos-query(-.*)?$",
      pod!~"^thanos-query-distributor(-.*)?$"
    }
  )
)

sum by (pod) (
  max_over_time(
